	private void setProposalForRegDirective(EObject regDirective, ICompletionProposalAcceptor acceptor, ContentAssistContext context) {
		AssemblerEngine assemblerEngine = AssemblerManager.getInstance().getAssemblyModel((Model)context.getRootModel());
		Map<String, List<EquDefinitionContainer>> containers = assemblerEngine.getEquSetManager().getEquContainer();
		for (Entry<String, List<EquDefinitionContainer>> entry : containers.entrySet()) {
			
			for (EquDefinitionContainer possibleEntry : entry.getValue()) {
				if (possibleEntry.getEquType() == EquDefinitionContainer.REG_DEFINITION) {
					RegDirective directive = (RegDirective)possibleEntry.getDirective();
					
					StringBuilder builder = new StringBuilder();
					for (Register register : directive.getOptions()) {
						if (builder.length() == 0) {
							builder.append(register.getLiteral());
						} else {
							builder.append("," + register.getLiteral());
						}
					}
					
					String msg = "Register definition: " + entry.getKey() + " (" + builder.toString() +")";
					acceptor.accept(createCompletionProposal(entry.getKey(), msg, null, context));
					
					break;		
				}
			}
		}
	}

